// The late-failure audit as a test: every backend rule (generated by tests/py/test_editor_rules.py,
// which runs each one through the add-on's preview) must have a row in src/lib/rules.ts saying how
// the editor handles it before apply; inline rows must resolve to a screen that shows the message.
import { describe, expect, it } from 'vitest';
import table from './fixtures/rule-errors.json';
import { RULES, surfaceOf } from '../src/lib/rules';
import { describePath, problemsFor, orphanProblems } from '../src/lib/problems';
import { haProblem } from '../src/lib/ha-rules';
import { trimBytes, utf8Bytes } from '../src/lib/codes';
import { activityId } from '../src/lib/activity-edit';
import { deviceIdFor, nameProblem } from '../src/lib/device-edit';
import { MAX_PAGES, MAX_PAGE_WIDGETS, pageCap, widgetCap } from '../src/lib/studio-model';
import type { Config } from '../src/lib/model';
import { refHref } from '../src/lib/refs';
import { changedWidgetIndexes } from '../src/lib/diff';
import { initial, likelyModels, type WState } from '../src/lib/wizard';

const rows = table as { rule: string; path: (string | number)[]; msg: string }[];

describe('rule table', () => {
  it('has a UI row for every backend rule and no stale rows', () => {
    expect(Object.keys(RULES).sort()).toEqual(rows.map((r) => r.rule).sort());
  });
  it('inline rules land on a screen that lists them; every error path reads as words', () => {
    for (const r of rows) {
      const s = surfaceOf(r.path);
      if (RULES[r.rule]?.how === 'inline') expect(s, r.rule).not.toBe('banner');
      if (s === 'device' || s === 'activity') {
        const d = describePath(r.path);
        expect(d.label.length, r.rule).toBeGreaterThan(0);
        const list = problemsFor([{ path: r.path, msg: r.msg }], s === 'device' ? 'devices' : 'activities', Number(r.path[1]));
        expect(list, r.rule).toHaveLength(1);
        expect(list[0]?.msg).toBe(r.msg);
      }
    }
    expect(orphanProblems([{ path: ['editor'], msg: 'x' }])).toHaveLength(1);
  });
  it('summary', () => {
    const n = (h: string) => Object.values(RULES).filter((r) => r.how === h).length;
    expect({ total: Object.keys(RULES).length, prevented: n('prevented'), inline: n('inline'), gap: n('gap') }).toEqual({ total: 58, prevented: 53, inline: 5, gap: 0 });
  });
});

describe('the prevention behind the "prevented" rows', () => {
  it('cuts names by UTF-8 bytes, not characters', () => {
    const t = trimBytes('Ж'.repeat(31));
    expect(utf8Bytes(t)).toBeLessThanOrEqual(31);
    expect(t.length).toBe(15);
  });
  it('generates ids that fit the 31-character pattern', () => {
    const long = 'a very long name that goes on and on and on';
    expect(activityId({}, long).length).toBeLessThanOrEqual(31);
    expect(deviceIdFor({ devices: [{ id: deviceIdFor({}, long) }] }, long).length).toBeLessThanOrEqual(31);
    expect(activityId({}, 'Off')).toBe('off_activity');
    expect(activityId({}, '!!!')).toMatch(/^[a-z0-9_]{1,31}$/);
  });
  it('refuses reserved and duplicate command names', () => {
    const d = { id: 'tv', commands: { up: {} } };
    expect(nameProblem(d, 'power_on')).toMatch(/reserved/);
    expect(nameProblem(d, 'input_x')).toMatch(/reserved/);
    expect(nameProblem(d, 'up')).toMatch(/Another/);
    expect(nameProblem(d, 'é'.repeat(16))).toMatch(/Shorten/);
  });
  it('checks Home Assistant actions like the server', () => {
    expect(haProblem('light.toggle', 'light.lamp')).toBeNull();
    expect(haProblem('shell_command.run', 'light.lamp')).toMatch(/not allowed/);
    expect(haProblem('light.toggle', 'Light.Lamp')).toMatch(/not an entity id/);
    expect(haProblem('light.toggle', 'light.lamp', { b: '{{ 1 }}' })).toMatch(/template/);
    expect(haProblem('light.toggle', 'light.lamp', { a: { b: { c: { d: { e: 1 } } } } })).toMatch(/deeper than 4/);
    expect(haProblem('light.toggle', 'light.lamp', { s: 'y'.repeat(201) })).toMatch(/over 200/);
    expect(haProblem('light.toggle', 'light.lamp', { a: Array.from({ length: 80 }, (_, i) => i) })).toMatch(/more than 64/);
    expect(haProblem('light.toggle', 'light.lamp', { entity_id: 'x' })).toMatch(/target/);
    expect(haProblem('light.toggle', 'light.lamp', Object.fromEntries(Array.from({ length: 12 }, (_, i) => [`k${i}`, 'y'.repeat(100)])))).toMatch(/1024 bytes/);
  });
  it('caps pages, widgets per page and soft keys', () => {
    const w = (n: number) => Array.from({ length: n }, (_, i) => ({ type: 'button', id: `b${i}` }));
    const full: Config = { pages: [{ id: 'a', widgets: w(MAX_PAGE_WIDGETS) }] };
    expect(widgetCap(full, 0)).toMatch(/at most 32/);
    expect(widgetCap({ pages: Array.from({ length: 4 }, (_, i) => ({ id: `p${i}`, widgets: w(26) })) }, 0)).toBeNull();
    expect(widgetCap({ pages: Array.from({ length: 6 }, (_, i) => ({ id: `p${i}`, widgets: w(22) })) }, 0)).toMatch(/soft keys/);
    expect(pageCap({ pages: Array.from({ length: MAX_PAGES }, (_, i) => ({ id: `p${i}`, widgets: [] })) })).toMatch(/at most 32/);
    expect(pageCap({ pages: [] })).toBeNull();
  });
});

describe('links and the wizard', () => {
  it('jumps from a use of a device to the key, widget or activity', () => {
    expect(refHref({ kind: 'key', layer: 'default', layerName: 'Default', key: 'volume_up' })).toBe('#/remote/default/volume_up');
    expect(refHref({ kind: 'key', layer: 'watch_tv', layerName: 'Watch TV', key: 'up' })).toBe('#/remote/watch_tv/up');
    expect(refHref({ kind: 'widget', page: 2, pageName: 'p', index: 3, label: 'x' })).toBe('#/remote/default/w2.3');
    expect(refHref({ kind: 'step', activity: 'watch_tv', activityName: 'Watch TV', list: 'steps', index: 0 })).toBe('#/activities/watch_tv');
  });
  it('likely models carry their archive file when the add-on sends it', () => {
    const s = { ...initial(), confirmed: { kind: 'on', action: {}, form: 'proto', count: 2, models: ['A', 'B'], model_files: ['a.json'], codesets: 1 } } as unknown as WState;
    expect(likelyModels(s)).toEqual([{ name: 'A', file: 'a.json' }, { name: 'B' }]);
  });
  it('marks the widgets that differ between two versions of a page', () => {
    const a = { widgets: [{ id: 'a', label: 'A' }, { id: 'b', label: 'B' }, { id: 'c', label: 'C' }] };
    const b = { widgets: [{ id: 'a', label: 'A' }, { id: 'b', label: 'B2' }, { id: 'd', label: 'D' }] };
    expect(changedWidgetIndexes(a, b)).toEqual({ before: [1, 2], after: [1, 2] });
    expect(changedWidgetIndexes(undefined, b).after).toEqual([0, 1, 2]);
  });
});
